// Merge doc1 and doc2, removing duplicates by word
const wordMap = new Map();

doc1.forEach(item => {
  wordMap.set(item.w.toLowerCase(), {
    word: item.w,
    level: item.l,
    meaning: item.t,
    type: item.pos || "İsim",
    example: ""
  });
});

doc2.forEach(item => {
  const key = item.w.toLowerCase();
  if (wordMap.has(key)) {
    const existing = wordMap.get(key);
    existing.level = item.l; // Doc 2 CEFR tags are strictly verified
    existing.meaning = item.t || existing.meaning;
    existing.example = item.ex || existing.example;
  } else {
    wordMap.set(key, {
      word: item.w,
      level: item.l,
      meaning: item.t,
      type: "Kelime",
      example: item.ex
    });
  }
});

const allWords = Array.from(wordMap.values());

// Sort into levels
const levels = {
  A1: [],
  A2: [],
  B1: [],
  B2: [],
  C1: [],
  C2: []
};

allWords.forEach(w => {
  if (levels[w.level]) {
    levels[w.level].push(w);
  } else {
    levels["B2"].push(w);
  }
});

Object.keys(levels).forEach(k => {
  levels[k].sort((a, b) => a.word.localeCompare(b.word));
  console.log(`${k} kelime sayısı: ${levels[k].length}`);
});

console.log('Toplam benzersiz kelime:', allWords.length);

fs.writeFileSync(path.join(__dirname, 'words_by_level.json'), JSON.stringify(levels, null, 2), 'utf-8');
fs.writeFileSync(path.join(__dirname, 'words_dataset.json'), JSON.stringify(allWords, null, 2), 'utf-8');

console.log('Veriler başarıyla words_by_level.json ve words_dataset.json dosyalarına kaydedildi!');
